import itertools, json

students = ["Louis", "Mollie", "Onyx", "Ryan", "Tiffany", "Yoshio"]
years = [1921, 1922, 1923, 1924]

def valid(assign):
    # assign: dict year -> student
    inv = {s: y for y, s in assign.items()}
    if assign[1923] not in ("Louis", "Tiffany"):
        return False
    if "Mollie" in inv and inv["Mollie"] not in (1921, 1922):
        return False
    if "Tiffany" in inv and "Ryan" not in inv:
        return False
    if "Ryan" in inv:
        if "Onyx" not in inv or inv["Onyx"] != inv["Ryan"] - 1:
            return False
    return True

sols = []
for perm in itertools.permutations(students, 4):
    assign = dict(zip(years, perm))
    if "Yoshio" in perm:
        continue
    if valid(assign):
        sols.append(assign)

def inproj(a, s):
    return s in a.values()

def inv(a, s):
    for y, st in a.items():
        if st == s:
            return y
    return None

checks = {
    "A": lambda a: not inproj(a, "Louis"),
    "B": lambda a: not inproj(a, "Ryan"),
    "C": lambda a: not inproj(a, "Tiffany"),
    "D": lambda a: inv(a, "Onyx") == 1922,
    "E": lambda a: inv(a, "Louis") == 1924,
}

could = [k for k, f in checks.items() if any(f(a) for a in sols)]

if len(could) == 1:
    print(json.dumps({"final_answer": could[0],
                      "evidence": {"num_solutions": len(sols), "could_be_true": could}}))
else:
    print("UNSUPPORTED")
